create table public.execution_bridge_attempts(
 id uuid primary key default gen_random_uuid(),attempt_key text not null unique,eligibility_evaluation_id uuid not null references public.trade_eligibility_evaluations(id),proposal_id uuid not null references public.trade_proposals(id),risk_snapshot_id uuid references public.risk_ledger_snapshots(id),account_observation_id uuid references public.account_state_observations(id),execution_intent_id uuid references public.execution_intents(id),bridge_policy_version text not null,outcome text not null check(outcome in('INTENT_CREATED','SAFETY_BLOCKED','DATA_BLOCKED','EXPIRED')),requirements jsonb not null,safety_requirements jsonb not null default '[]',information_cutoff_at timestamptz not null,available_at timestamptz not null,result_hash text not null,created_at timestamptz not null default now(),check(information_cutoff_at<=available_at),unique(eligibility_evaluation_id,bridge_policy_version)
);
create index execution_bridge_outcome_idx on public.execution_bridge_attempts(outcome,created_at desc);create trigger execution_bridge_attempts_immutable before update or delete on public.execution_bridge_attempts for each row execute function public.prevent_execution_history_mutation();alter table public.execution_bridge_attempts enable row level security;create policy "public read execution bridge" on public.execution_bridge_attempts for select using(true);grant select on public.execution_bridge_attempts to anon,authenticated;grant all on public.execution_bridge_attempts to service_role;
alter table public.ingestion_runs drop constraint if exists ingestion_runs_job_kind_check;alter table public.ingestion_runs add constraint ingestion_runs_job_kind_check check(job_kind in('stock_quotes','wallet_transactions','wallet_discovery','crypto_market','wallet_pnl','wallet_evidence','fast_flow','wallet_clustering','jackpot_collector','jackpot_outcomes','market_events','paper_eligibility','paper_execution','paper_exits','paper_valuation','performance','fx','qualification','data_gap_closure','simulation','historical_replay','forecast_catalyst','expert_knowledge','baseline_forecast','forecast_performance','forecast_scheduler','forecast_outcomes','specialist_agents','news_ingestion','catalyst_classification','consensus','agent_performance','market_regime','meta_agent','meta_readiness','strategy_pattern_lab','candle_ingestion','ai_explanations','strategy_intelligence','execution','trade_eligibility','account_state','execution_bridge'));
